import { solveColumns } from '../arithmetic/solveColumns'
import type { CheckResult, ColumnStep, Question } from '../types'

/**
 * Kukoos's words as message keys + parameters. The copy lives in content/hints.en.json
 * (hand-written now, regenerated by build-time AI in F09). Keys use "group:name".
 */
export type MessageParams = Readonly<Record<string, string | number>>
export interface Message {
  key: string
  params: MessageParams
}

const PLACE_NAMES = ['Ones', 'Tens', 'Hundreds'] as const
const msg = (key: string, params: MessageParams = {}): Message => ({ key, params })

/** Fills `{name}` placeholders. Unknown placeholders are left visible so tests can catch them. */
export function formatMessage(template: string, params: MessageParams): string {
  return template.replace(/\{(\w+)\}/g, (whole, name: string) =>
    name in params ? String(params[name]) : whole,
  )
}

function stepsOf(q: Question): ColumnStep[] | undefined {
  const m = q.arithmetic
  return m && m.unknown === 'result' ? solveColumns(m.a, m.b, m.op) : undefined
}

/** The hint after a miss: targeted when we know the misconception, otherwise the skill's hint. */
export function hintFor(q: Question, result: CheckResult | null): Message {
  const misconception = result?.misconception
  const steps = stepsOf(q)
  if (misconception) {
    if (misconception === 'sub.smallerFromLarger') {
      const s = steps?.find((x) => x.received)
      if (s) return msg(`misconception:${misconception}`, { a: s.working - 10, b: s.bottom })
    } else if (misconception === 'add.forgotCarry') {
      const s = steps?.find((x) => x.carryOut === 1)
      if (s) return msg(`misconception:${misconception}`, { x: s.top + s.bottom + s.carryIn })
    } else {
      return msg(`misconception:${misconception}`)
    }
  }
  const textHint = q.hints.find((h) => h.type === 'text')
  if (textHint) return msg(`hint:${textHint.key}`)
  if (q.arithmetic) return msg('hint:column')
  return msg('hint:default')
}

/** What Kukoos says on the second miss, with the answer. */
export function solutionFor(q: Question): Message {
  const { answer } = q
  const shown = answer.type === 'boolean' ? (answer.value ? 'true' : 'false') : String(answer.value)
  return msg('solution:answer', { answer: shown })
}

/**
 * Guided column mode: one message per column, ones first, derived from solver steps.
 * Subtraction says when to trade (and to open a hundred when the tens is 0);
 * addition says when a column makes more than 9.
 */
export function guidedSteps(q: Question): Message[] {
  if (q.payload.kind !== 'column') return []
  const { a, b, op } = q.payload
  const steps = solveColumns(a, b, op)
  return steps.map((s, i) => {
    const place = PLACE_NAMES[i] ?? PLACE_NAMES[2]
    if (op === '+') {
      const plus = s.carryIn ? ' + 1' : ''
      return s.carryOut
        ? msg('guided:add.carry', { place, a: s.top, b: s.bottom, plus })
        : msg('guided:add', { place, a: s.top, b: s.bottom, plus })
    }
    // A lending zero (403's tens) arrives already traded: it just shows 9.
    const passedThrough = s.top === 0 && s.lent && s.received
    if (s.received && !passedThrough) {
      const nextTop = steps[i + 1]?.top
      return msg(nextTop === 0 ? 'guided:sub.tradeAcrossZero' : 'guided:sub.trade', {
        place,
        a: s.working - 10,
        b: s.bottom,
      })
    }
    return msg('guided:sub.ready', { place, a: s.working, b: s.bottom })
  })
}
